const rtdal010256Source0001 = "`c.xts` <-\nfunction(...) {\n  .External(C_rbindXts, dup=FALSE, ...)\n}"

const rtdal010256Source0002 = `rbind.xts <- function(..., deparse.level=1)
{
  .External(C_rbindXts, dup=FALSE, ...)
}`

const rtdal010256Source0003 = "`.rbind.xts` <-\nfunction(..., deparse.level=1) {\n  dots <- list(...)\n  if(length(dots) < 2) return(dots[[1]])\n  x <- dots[[1]]\n  dots <- dots[-1]\n\n  while( length(dots) > 0 ) {\n    y <- dots[[1]]\n    if( length(dots) > 0)\n      dots <- dots[-1]\n    if(!is.null(colnames(y)) && colnames(x) != colnames(y))\n      warning('column names differ')\n    x <- .Call(C_do_rbind_xts,x,y,FALSE)\n  }\n  return(x)\n}"

