const rtdal010257Source0001 = `coredata.xts <- function(x, fmt=FALSE, ...) {
  x.attr <- attributes(x)

  if(is.character(fmt)) {
    tformat(x) <- fmt
    fmt <- TRUE
  }
  
  if(length(x) > 0 && fmt) {
    if(!is.null(tformat(x))) {
      x.attr$dimnames <- list(format(index(x), format=tformat(x)),
                              dimnames(x)[[2]])
      tformat(x) <- NULL  # remove before printing
    } else {
      x.attr$dimnames <- list(format(index(x)),dimnames(x)[[2]])
    }
      #attributes not to be kept
    original.attr <- x.attr[!names(x.attr) %in%
                          c('dim','dimnames')]
    if(is.null(dim(x))) {
      xx <- structure(coredata(x), names=x.attr$dimnames[[1]])
    } else {
      xx <- structure(coredata(x), dim=dim(x), dimnames=x.attr$dimnames) 
    }
    for(i in names(original.attr)) {
      attr(xx,i) <- NULL
    }
    return(xx)
  }

  if(length(x) == 0) {
    xx <- NextMethod(x)
    attr(xx, ".indexCLASS") <- NULL
    attr(xx, "tclass") <- NULL
    # Remove tz attrs (object created before 0.10-3)
    attr(xx, ".indexTZ") <- NULL
    attr(xx, "tzone") <- NULL
    return(xx)
  } else 
  return(.Call(C_coredata_xts, x))

}`

const rtdal010257Source0002 = "`xcoredata.default` <-\nfunction(x,...) {\n  x.attr <- attributes(x)\n  original.attr <- x.attr[!names(x.attr) %in%\n                          c('dim','dimnames')]\n  original.attr\n}"

const rtdal010257Source0003 = "`xcoredata` <-\nfunction(x,...) {\n  UseMethod('xcoredata')\n}"

const rtdal010257Source0005 = "`xcoredata<-.default` <- function(x,value) {\n  if(is.null(value)) {\n    return(coredata(x))\n  } else {\n    for(att in names(value)) {\n      if(!att %in% c('dim','dimnames'))\n        attr(x,att) <- value[[att]]\n    }\n  return(x)\n  }\n}"

const rtdal010257Source0008 = "`xtsAttributes<-.xts` <-\nfunction(x,value) {\n  if(is.null(value)) {\n    for(nm in names(xtsAttributes(x))) {\n      attr(x,nm) <- NULL\n    }\n  } else\n  for(nv in names(value)) {\n    if(!nv %in% c('dim','dimnames','index','class','.CLASS','.ROWNAMES','.CLASSnames'))\n      attr(x,nv) <- value[[nv]]\n  }\n  # Remove tz attrs (object created before 0.10-3)\n  attr(x, \".indexTZ\") <- NULL\n  attr(x, \"tzone\") <- NULL\n  # Remove index class attrs (object created before 0.10-3)\n  attr(x, \".indexCLASS\") <- NULL\n  attr(x, \"tclass\") <- NULL\n  # Remove index format attr (object created before 0.10-3)\n  attr(x, \".indexFORMAT\") <- NULL\n  x\n}"

