const rtdal010263Source0001 = `index.xts <-
function(x, ...) {
  value <- tclass(x)
  if(is.null(value) || !nzchar(value[1L])) {
    warning("index does not have a ", sQuote("tclass"), " attribute\n",
            "    returning c(\"POSIXct\", \"POSIXt\")")
    ix <- .index(x)
    attr(ix, "tclass") <- attr(ix, "class") <- c("POSIXct", "POSIXt")
    return(ix)
  }
  #  if tclass is Date, POSIXct time is set to 00:00:00 GMT. Convert here
  #  to avoid ugly and hard to debug TZ conversion.  What will this break? 
  if(value[[1]] == "Date")
    #return( as.Date(.index(x)/86400) )
    return( structure(.index(x) %/% 86400, class="Date")) 
    

  #x.index  <- structure(.index(x), class=c("POSIXct","POSIXt"))
  x.index  <- .POSIXct(.index(x), tz=attr(.index(x), "tzone"))

  if(!is.list(value)) 
    value <- as.list(value)

  switch(value[[1]],
    multitime = as.Date(as.character(x.index)),
    POSIXt = {
      # get specific ct/lt value
      do.call(paste('as',value[[2]],sep='.'),list(x.index))
    },
    POSIXct = as.POSIXct(x.index),
    POSIXlt = as.POSIXlt(x.index),
    timeDate = {
      if(!requireNamespace("timeDate", quietly=TRUE))
          stop("package:",dQuote("timeDate"),"cannot be loaded.")
      timeDate::as.timeDate(x.index)
    },
    chron = ,
    dates = {
      if(!requireNamespace("chron", quietly=TRUE))
        stop("package:",dQuote("chron"),"cannot be loaded.")
      chron::as.chron(format(x.index))
    },
    #Date = as.Date(as.character(x.index)),  # handled above
    yearmon = as.yearmon(x.index),
    yearqtr = as.yearqtr(x.index),
    stop(paste('unsupported',sQuote('tclass'),'indexing type:',value[[1]]))
  )
}`

const rtdal010263Source0002 = "`index<-.xts` <- function(x, value) {\n  if(length(index(x)) != length(value)) stop('length of index vectors does not match')\n\n  if( !timeBased(value) ) \n    stop(paste('unsupported',sQuote('index'),\n               'index type of class',sQuote(class(value))))\n\n  # copy original index attributes\n  ixattr <- attributes(attr(x, 'index'))\n\n  # set index to the numeric value of the desired index class\n  if(inherits(value,\"Date\"))\n    attr(x, 'index') <- structure(unclass(value)*86400, tclass=\"Date\", tzone=\"UTC\")\n  else attr(x, 'index') <- as.numeric(as.POSIXct(value))\n\n  # ensure new index is sorted\n  if(!isOrdered(.index(x), strictly=FALSE))\n    stop(\"new index needs to be sorted\")\n\n  # set tclass attribute to the end-user specified class\n  attr(attr(x, 'index'), 'tclass') <- class(value)\n\n  # set tzone attribute\n  if(isClassWithoutTZ(object = value)) {\n    attr(attr(x, 'index'), 'tzone') <- 'UTC'\n  } else {\n    if (is.null(attr(value, 'tzone'))) {\n      # ensure index has tzone attribute if value does not\n      attr(attr(x, 'index'), 'tzone') <- ixattr[[\"tzone\"]]\n    } else {\n      attr(attr(x, 'index'), 'tzone') <- attr(value, 'tzone')\n    }\n  }\n  return(x)\n}"

const rtdal010263Source0005 = "`.index` <- function(x, ...) {\n  if(is.list(attr(x, \"index\"))) {\n    attr(x, 'index')[[1]]\n  } else attr(x, \"index\")\n}"

const rtdal010263Source0006 = "`.index<-` <- function(x, value) {\n  if(timeBased(value)) {\n    if(inherits(value, 'Date')) {\n      attr(x, 'index') <- as.numeric(value)\n    } else {\n      attr(x, 'index') <- as.numeric(as.POSIXct(value))\n    }\n  } else \n  if(is.numeric(value)) {\n    attr(value, 'tclass') <- tclass(x)\n    attr(value, 'tzone') <- tzone(x)\n    attr(x, 'index') <- value\n  } else stop(\".index is used for low level operations - data must be numeric or timeBased\")\n  return(x)\n}"

const rtdal010263Source0021 = "`convertIndex` <-\nfunction(x,value) {\n  tclass(x) <- value\n  x\n}"

