const rtdal010291Source0001 = `tclass <-
function(x, ...) {
  UseMethod('tclass')
}`

const rtdal010291Source0002 = `tclass.default <-
function(x, ...)
{
  attr(x, "tclass")
}`

const rtdal010291Source0003 = `tclass.xts <-
function(x, ...)
{
  tclass <- attr(attr(x, "index"), "tclass")

  # For xts objects created pre-0.10.3
  if (is.null(tclass)) {
    # no tclass on the index
    sq_tclass <- sQuote("tclass")
    sq_both <- paste(sq_tclass, "or", sQuote(".indexCLASS"))

    warn_msg <-
      paste0("index does not have a ", sq_tclass, " attribute")

    tclass <- attr(x, "tclass")
    if (is.null(tclass)) {
      # no tclass on the xts object, look for .indexCLASS
      tclass <- attr(x, ".indexCLASS")
    }

    if (is.null(tclass)) {
      # no .indexCLASS on the xts object
      tc <- c("POSIXct", "POSIXt")
      warn_msg <- paste0(warn_msg, "\n  and xts object does not have a ",
                         sq_both, " attribute\n", "  returning ", dQuote(tc))
      warning(warn_msg)
      return(tc)
    }

    sym <- deparse(substitute(x))
    warning(warn_msg, "\n use ", sym,
            " <- xts:::.update_index_attributes(", sym, ") to update the object")
  }
  return(tclass)
}`

const rtdal010291Source0005 = "`tclass<-.default` <-\nfunction(x, value)\n{\n  if (!is.null(value)) {\n    value <- as.character(value)\n  }\n  attr(x, \"tclass\") <- value\n  x\n}"

const rtdal010291Source0008 = "`tclass<-.xts` <-\nfunction(x, value) {\n  if(!is.character(value) && length(value) != 1)\n    stop('improperly specified value for tclass')\n\n  # remove 'POSIXt' from value, to prevent tclass(x) <- 'POSIXt'\n  value <- value[!value %in% \"POSIXt\"]\n  if(length(value)==0L)\n    stop(paste('unsupported',sQuote('tclass'),'indexing type: POSIXt'))\n\n  if(!value[1] %in% c('dates','chron','POSIXlt','POSIXct','Date','timeDate','yearmon','yearqtr','xtime') )\n       stop(paste('unsupported',sQuote('tclass'),'indexing type:',as.character(value[[1]])))\n\n  # Add 'POSIXt' virtual class\n  if(value %in% c('POSIXlt','POSIXct'))\n    value <- c(value,'POSIXt')\n\n  # all index related meta-data will be stored in the index\n  # as attributes\n  if(isClassWithoutTZ(value)) {\n    attr(attr(x,'index'), 'tzone') <- 'UTC'\n  }\n  attr(attr(x,'index'), 'tclass') <- value\n\n  x_has_tz <- !isClassWithoutTZ(x)\n  if(x_has_tz && isClassWithoutTZ(value)) {\n    # update index values to midnight UTC (this also changes the tzone)\n    index(x) <- index(x)\n  }\n\n  # Remove class attrs (object created before 0.10-3)\n  attr(x, \".indexCLASS\") <- NULL\n  attr(x, \"tclass\") <- NULL\n\n  x\n}"

