const rtdal010306Source0003 = `register_s3_method <-
function(pkg, generic, class, fun = NULL)
{
  stopifnot(is.character(pkg), length(pkg) == 1L)
  stopifnot(is.character(generic), length(generic) == 1L)
  stopifnot(is.character(class), length(class) == 1L)

  if (is.null(fun)) {
    fun <- get(paste0(generic, ".", class), envir = parent.frame())
  } else {
    stopifnot(is.function(fun))
  }

  if (isNamespaceLoaded(pkg)) {
    registerS3method(generic, class, fun, envir = asNamespace(pkg))
  }

  # Always register hook in case package is later unloaded & reloaded
  setHook(
    packageEvent(pkg, "onLoad"),
    function(...) {
      registerS3method(generic, class, fun, envir = asNamespace(pkg))
    }
  )
}`

const rtdal010306Source0004 = ".onAttach <- function(libname, pkgname)\n{\n  warn_dplyr_lag <- getOption(\"xts.warn_dplyr_breaks_lag\", TRUE)\n\n  dplyr_will_mask_lag <- conflictRules(\"dplyr\")\n  if (is.null(dplyr_will_mask_lag)) {\n    dplyr_will_mask_lag <- TRUE\n  } else {\n    dplyr_will_mask_lag <- all(dplyr_will_mask_lag$exclude != \"lag\")\n  }\n\n  if (warn_dplyr_lag && dplyr_will_mask_lag) {\n      ugly_message <- \"\n######################### Warning from 'xts' package ##########################\n#                                                                             #\n# The dplyr lag() function breaks how base R's lag() function is supposed to  #\n# work, which breaks lag(my_xts). Calls to lag(my_xts) that you type or       #\n# source() into this session won't work correctly.                            #\n#                                                                             #\n# Use stats::lag() to make sure you're not using dplyr::lag(), or you can add #\n# conflictRules('dplyr', exclude = 'lag') to your .Rprofile to stop           #\n# dplyr from breaking base R's lag() function.                                #\n#                                                                             #\n# Code in packages is not affected. It's protected by R's namespace mechanism #\n# Set `options(xts.warn_dplyr_breaks_lag = FALSE)` to suppress this warning.  #\n#                                                                             #\n###############################################################################\"\n    if (\"package:dplyr\" %in% search()) {\n      packageStartupMessage(ugly_message)\n    } else {\n      setHook(packageEvent(\"dplyr\", \"attach\"),\n              function(...) packageStartupMessage(ugly_message))\n    }\n  }\n}"

const rtdal010306Source0005 = `.onLoad <- function(libname, pkgname)
{
  if (getRversion() < "3.6.0") {
    register_s3_method("timeSeries", "as.timeSeries", "xts")
    if (utils::packageVersion("zoo") < "1.8.5") {
      # xts:::as.zoo.xts was copied to zoo:::as.zoo.xts in zoo 1.8-5
      register_s3_method("zoo", "as.zoo", "xts")
    }
  }
  invisible()
}`

