const rtdal010375Source0001 = `test_that("Basic matrices work", {
  
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  #' Logical
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  mat  <- matrix(c(TRUE, FALSE), 2, 3)
  json <- write_json_str(mat)
  expect_identical(
    json,
    "[[true,true,true],[false,false,false]]"
  )
  mat2 <- read_json_str(json)
  expect_identical(mat2, mat)
  
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  #' Integer
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  mat  <- matrix(1:6, 2, 3)
  json <- write_json_str(mat)
  expect_identical(
    json,
    "[[1,3,5],[2,4,6]]"
  )
  mat2 <- read_json_str(json)
  expect_identical(mat2, mat)
  
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  #' Numeric
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  mat  <- matrix(as.numeric(1:6), 2, 3)
  json <- write_json_str(mat)
  expect_identical(
    json,
    "[[1.0,3.0,5.0],[2.0,4.0,6.0]]"
  )
  mat2 <- read_json_str(json)
  expect_identical(mat2, mat)
  
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  #' Character
  #~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
  mat  <- matrix(as.character(1:6), 2, 3)
  json <- write_json_str(mat)
  expect_identical(
    json,
    '[["1","3","5"],["2","4","6"]]'
  )
  mat2 <- read_json_str(json)
  expect_identical(mat2, mat)
  
})`

