const rtdal010395Source0001 = `test_that("prevent no visible bindings", {
  skip_if_not_installed("codetools")

  nums <- function() {
    c(one, two) %<-% list(1, 2)
    four %<-% 4
    c(one, two, three, four)
  }

  problems <- ""

  codetools::checkUsage(
    fun = nums,
    report = function(x) {
      problems <<- paste0(problems, x)
    }
  )

  expect_false(grepl("one", problems))
  expect_false(grepl("two", problems))
  expect_false(grepl("four", problems))
  expect_true(grepl("three", problems))
})`

