const rtdal010402Source0003 = `get_zip_data <- function(
  files,
  recurse,
  keep_path,
  include_directories,
  keys = NULL
) {
  list <- if (is.null(keys)) {
    if (keep_path) {
      get_zip_data_path(files, recurse)
    } else {
      get_zip_data_nopath(files, recurse)
    }
  } else {
    get_zip_data_keys(files, keys, recurse, keep_path)
  }

  if (!include_directories) {
    list <- list[!list$dir, ]
  }

  list
}`

const rtdal010402Source0006 = `get_zip_data_path <- function(files, recurse) {
  if (recurse && length(files)) {
    data <- do.call(rbind, lapply(files, get_zip_data_path_recursive))
    dup <- duplicated(data$files)
    if (any(dup)) {
      data <- data <- data[!dup, drop = FALSE]
    }
    data
  } else {
    files <- ignore_dirs_with_warning(files)
    data_frame(
      key = files,
      files = files,
      dir = rep(FALSE, length(files))
    )
  }
}`

const rtdal010402Source0008 = "warn_for_colon <- function(files) {\n  if (any(grepl(\":\", files, fixed = TRUE))) {\n    warning(\n      \"Some paths include a `:` character, this might cause issues \",\n      \"when uncompressing the zip file on Windows.\"\n    )\n  }\n}"

const rtdal010402Source0010 = `get_zip_data_nopath <- function(files, recurse) {
  if ("." %in% files) {
    files <- c(setdiff(files, "."), dir(all.files = TRUE, no.. = TRUE))
  }
  if (recurse && length(files)) {
    data <- do.call(rbind, lapply(files, get_zip_data_nopath_recursive))
    dup <- duplicated(data$files)
    if (any(dup)) {
      data <- data[!dup, drop = FALSE]
    }
    data
  } else {
    files <- ignore_dirs_with_warning(files)
    data_frame(
      key = basename(files),
      file = files,
      dir = rep(FALSE, length(files))
    )
  }
}`

const rtdal010402Source0012 = `get_zip_data_path_recursive <- function(x) {
  if (file.info(x)$isdir) {
    files <- c(
      x,
      dir(
        x,
        recursive = TRUE,
        full.names = TRUE,
        all.files = TRUE,
        include.dirs = TRUE,
        no.. = TRUE
      )
    )
    dir <- file.info(files)$isdir
    data_frame(
      key = ifelse(dir, paste0(files, "/"), files),
      file = normalizePath(files),
      dir = dir
    )
  } else {
    data_frame(
      key = x,
      file = normalizePath(x),
      dir = FALSE
    )
  }
}`

const rtdal010402Source0014 = `mkdirp <- function(x, ...) {
  dir.create(x, showWarnings = FALSE, recursive = TRUE, ...)
}`

const rtdal010402Source0015 = "need_packages <- function(pkgs, what = \"this function\") {\n  for (p in pkgs) {\n    if (!requireNamespace(p, quietly = TRUE)) {\n      stop(sprintf(\"The `%s` package is needed for %s\", p, what))\n    }\n  }\n}"

const rtdal010402Source0016 = `enc2c <- function(x) {
  if (.Platform$OS.type == "windows") {
    enc2utf8(x)
  } else {
    enc2native(x)
  }
}`

const rtdal010402Source0020 = "is_true_option <- function(name) {\n  opt <- getOption(name)\n  if (is.null(opt)) {\n    NULL\n  } else if (isTRUE(opt)) {\n    TRUE\n  } else if (isFALSE(opt)) {\n    FALSE\n  } else {\n    stop(sprintf(\"Option `%s` must be TRUE, FALSE\", name))\n  }\n}"

const rtdal010402Source0023 = "is_true_env_var <- function(name) {\n  env <- tolower(Sys.getenv(name, unset = NA))\n  if (is.na(env)) {\n    NULL\n  } else if (env %in% true_values) {\n    TRUE\n  } else if (env %in% false_values) {\n    FALSE\n  } else {\n    stop(sprintf(\"Environment variable `%s` must be TRUE or FALSE\", name))\n  }\n}"

