const rtdal010404Source0002 = `call_with_cleanup <- function(ptr, ...) {
  # R_ExecWithCleanup (inside cleancall) pushes a CTXT_CCODE context with
  # call=R_NilValue, so Rf_error() loses the calling function name. Capture
  # it here and restore it on errors that arrive without a call.
  caller <- sys.call(sys.nframe() - 1)
  withCallingHandlers(
    .Call(c_cleancall_call, pairlist(ptr, ...), parent.frame()),
    error = function(e) {
      if (is.null(conditionCall(e))) {
        e$call <- caller
        stop(e)
      }
    }
  )
}`

const rtdal010404Source0007 = "zip_internal <- function(\n  zipfile,\n  files,\n  recurse,\n  compression_level,\n  append,\n  root,\n  keep_path,\n  include_directories,\n  keys = NULL,\n  password = NULL,\n  encryption = \"aes256\"\n) {\n  if (!is.null(keys)) {\n    if (length(keys) != length(files)) {\n      stop(\"`keys` must have the same length as `files`\")\n    }\n  }\n\n  zipfile <- path.expand(zipfile)\n  if (dir.exists(zipfile)) {\n    stop(\"zip file at `\", zipfile, \"` already exists and it is a directory\")\n  }\n  oldwd <- setwd(root)\n  on.exit(setwd(oldwd), add = TRUE)\n\n  if (!all(file.exists(files))) {\n    stop(\"Some files do not exist\")\n  }\n\n  data <- get_zip_data(\n    files,\n    recurse,\n    keep_path,\n    include_directories,\n    keys = keys\n  )\n  data$key <- fix_absolute_paths(data$key)\n  warn_for_colon(data$key)\n  warn_for_dotdot(data$key)\n\n  fi <- file.info(data$file, extra_cols = FALSE)\n  show_progress <- is_progress_enabled()\n  total_bytes <- if (show_progress) {\n    sum(fi$size[!data$dir], na.rm = TRUE)\n  } else {\n    NA_real_\n  }\n\n  pw <- resolve_password(password)\n  enc <- if (is.null(pw)) 0L else encryption_code(encryption)\n\n  call_with_cleanup(\n    c_R_zip_zip,\n    enc2c(zipfile),\n    enc2c(data$key),\n    enc2c(data$file),\n    data$dir,\n    fi$mtime,\n    as.integer(compression_level),\n    append,\n    total_bytes,\n    pw,\n    enc\n  )\n\n  invisible(zipfile)\n}"

const rtdal010404Source0008 = "zip_list <- function(zipfile, encoding = NULL) {\n  if (startsWith(zipfile, \"http://\") || startsWith(zipfile, \"https://\")) {\n    return(zip_list_url(zipfile, encoding))\n  }\n  zipfile <- enc2c(normalizePath(zipfile))\n  res <- .Call(c_R_zip_list, zipfile, encoding)\n  if (Sys.getenv(\"PKGCACHE_NO_PILLAR\") == \"\") {\n    requireNamespace(\"pillar\", quietly = TRUE)\n  }\n  df <- data_frame(\n    filename = res[[1]],\n    compressed_size = res[[2]],\n    uncompressed_size = res[[3]],\n    timestamp = as.POSIXct(res[[4]], tz = \"UTC\", origin = \"1970-01-01\")\n  )\n  Encoding(df$filename) <- \"UTF-8\"\n  df$permissions <- as.octmode(res[[5]])\n  df$crc32 <- as.hexmode(res[[6]])\n  df$offset <- res[[7]]\n  # names are the same as in `fs::file_info()`\n  df$type <- file_types[res[[8]] + 1L]\n  df$encryption <- encryption_types[res[[9]] + 2L]\n  df\n}"

const rtdal010404Source0011 = `unzip <- function(
  zipfile,
  files = NULL,
  overwrite = TRUE,
  junkpaths = FALSE,
  exdir = ".",
  encoding = NULL,
  password = NULL
) {
  if (
    length(zipfile) == 1 &&
      (startsWith(zipfile, "http://") || startsWith(zipfile, "https://"))
  ) {
    return(unzip_url(zipfile, files, overwrite, junkpaths, exdir, encoding))
  }
  stopifnot(
    is_character(zipfile),
    length(zipfile) >= 1,
    is_character_or_null(files),
    is_flag(overwrite),
    is_flag(junkpaths),
    is_string(exdir)
  )

  if (
    length(zipfile) > 1 &&
      is.null(files) &&
      isTRUE(overwrite) &&
      !isTRUE(junkpaths) &&
      is.null(encoding) &&
      !any(startsWith(zipfile, "http://") | startsWith(zipfile, "https://"))
  ) {
    pw <- resolve_password(password)
    passwords <- if (!is.null(pw)) rawToChar(pw) else NULL
    return(threaded_unzip(zipfile, exdirs = exdir, passwords = passwords))
  }

  if (length(zipfile) > 1) {
    results <- lapply(zipfile, function(zf) {
      unzip(
        zf,
        files = files,
        overwrite = overwrite,
        junkpaths = junkpaths,
        exdir = exdir,
        encoding = encoding,
        password = password
      )
    })
    return(invisible(do.call(rbind, results)))
  }

  zipfile <- enc2c(normalizePath(zipfile))
  if (!is.null(files)) {
    files <- enc2c(files)
  }
  exdir <- sub("/+$", "", exdir)
  mkdirp(exdir)
  exdir <- enc2c(normalizePath(exdir))

  pw <- resolve_password(password)

  res <- call_with_cleanup(
    c_R_zip_unzip,
    zipfile,
    files,
    overwrite,
    junkpaths,
    exdir,
    encoding,
    is_progress_enabled(),
    pw
  )

  if (Sys.getenv("PKGCACHE_NO_PILLAR") == "") {
    requireNamespace("pillar", quietly = TRUE)
  }
  df <- data_frame(
    filename = res[[1]],
    compressed_size = res[[2]],
    uncompressed_size = res[[3]],
    timestamp = as.POSIXct(res[[4]], tz = "UTC", origin = "1970-01-01")
  )
  Encoding(df$filename) <- "UTF-8"
  df$permissions <- as.octmode(res[[5]])
  df$crc32 <- as.hexmode(res[[6]])
  df$offset <- res[[7]]
  df$type <- file_types[res[[8]] + 1L]
  df$path <- res[[9]]
  Encoding(df$path) <- "UTF-8"

  invisible(df)
}`

