const rtdal010413Source0001 = `test_that("zip_list works with range request server", {
  skip_if_not_installed("curl")
  skip_if_not_installed("webfakes")

  za <- http_fixture()
  url <- range_server$url(zip_path(za$zip))

  expect_snapshot(zip_list_snapshot(url, za$ex), transform = transform_offset)
})`

const rtdal010413Source0002 = `test_that("unzip works with range request server", {
  skip_if_not_installed("curl")
  skip_if_not_installed("webfakes")

  za <- http_fixture()
  url <- range_server$url(zip_path(za$zip))

  exdir <- test_temp_dir()
  unzip(url, exdir = exdir)

  expect_snapshot(extracted_tree(exdir, za$ex))
})`

const rtdal010413Source0003 = `test_that("unzip extracts specific files with range request server", {
  skip_if_not_installed("curl")
  skip_if_not_installed("webfakes")

  za <- http_fixture()
  url <- range_server$url(zip_path(za$zip))

  exdir <- test_temp_dir()
  target <- paste0(basename(za$ex), "/file1")
  unzip(url, files = target, exdir = exdir)

  expect_snapshot(extracted_tree(exdir, za$ex))
})`

